import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type StatusId = 'active' | 'paused' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  quota: number;
  status: StatusId;
};

const STATUSES = [
  { id: 'active', label: 'Активные', tone: 'success' },
  { id: 'paused', label: 'На паузе', tone: 'warning' },
  { id: 'over', label: 'Превышение', tone: 'danger' },
  { id: 'archived', label: 'Архив', tone: 'default' },
] as const;

const ALL_STATUSES: StatusId[] = STATUSES.map((status) => status.id);

const PROJECTS: Project[] = [
  { id: 'p-1', name: 'Контекстный индекс', quota: 72, status: 'active' },
  { id: 'p-2', name: 'Выгрузка логов', quota: 34, status: 'paused' },
  { id: 'p-3', name: 'Поиск по документам', quota: 108, status: 'over' },
  { id: 'p-4', name: 'Разметка датасета', quota: 55, status: 'active' },
  { id: 'p-5', name: 'Миграция биллинга', quota: 91, status: 'active' },
  { id: 'p-6', name: 'Старый парсер', quota: 12, status: 'archived' },
  { id: 'p-7', name: 'Отчёты для финансов', quota: 63, status: 'paused' },
  { id: 'p-8', name: 'Синтез речи', quota: 120, status: 'over' },
  { id: 'p-9', name: 'Сбор фидбека', quota: 28, status: 'active' },
  { id: 'p-10', name: 'Прототип редактора', quota: 47, status: 'archived' },
  { id: 'p-11', name: 'Мониторинг очередей', quota: 84, status: 'active' },
  { id: 'p-12', name: 'Импорт контактов', quota: 19, status: 'paused' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [selected, setSelected] = useState<StatusId[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => selected.includes(project.status)),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = visible.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const toggle = (id: StatusId) => {
    setSelected((current) =>
      current.includes(id) ? current.filter((item) => item !== id) : [...current, id],
    );
    setPage(1);
  };

  const reset = () => {
    setSelected(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <h2
        style={{
          margin: 0,
          fontFamily: 'var(--jx-font-display)',
          fontSize: '20px',
          color: 'var(--jx-text)',
        }}
      >
        Расход по проектам
      </h2>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => {
          const isActive = selected.includes(status.id);
          return (
            <JxChip
              key={status.id}
              active={isActive}
              removable={isActive}
              onRemove={() => toggle(status.id)}
              onClick={() => toggle(status.id)}
            >
              {status.label}
            </JxChip>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные статусы не подходит ни один проект."
          action={
            <JxButton variant="primary" onClick={reset}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {rows.map((project) => {
              const status = STATUSES.find((item) => item.id === project.status);
              return (
                <div
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 0',
                    borderBottom: '1px solid var(--jx-rule)',
                  }}
                >
                  <span style={{ flex: 1, minWidth: 0 }}>{project.name}</span>
                  <JxProgressCircle value={project.quota} showValue />
                  <JxBadge tone={status?.tone ?? 'default'} dot>
                    {status?.label ?? project.status}
                  </JxBadge>
                </div>
              );
            })}
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '12px' }}>
            <span style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>
              Проектов: {visible.length}
            </span>
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          </div>
        </>
      )}
    </section>
  );
}

